[
  {
    "alert_id": "EX3_001",
    "title": "Hypothyroidism undertreated despite levothyroxine",
    "message": "TSH is 12.4 mIU/L (target below 4.5) with low Free T4, confirming persistent hypothyroidism. The patient reports often forgetting the thyroid tablet, which is the likely primary cause of poor control. Symptoms of weight gain, tiredness, feeling cold, constipation, dry skin, periorbital puffiness, and delayed ankle reflexes are all classic hypothyroid features. This is a compounding risk: untreated hypothyroidism independently causes weight gain, hyperlipidaemia, and bradycardia, and may be the dominant driver of this patient's weight gain rather than DTG. The clinician's plan does not address the elevated TSH, missed doses, or the need for dose escalation.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Address adherence barriers for levothyroxine, repeat TSH after consistent dosing, and uptitrate dose if TSH remains elevated. Reassess weight attribution to DTG after thyroid control is achieved.",
    "citations": []
  },
  {
    "alert_id": "EX3_002",
    "title": "Weight gain attributed to DTG may be confounded by hypothyroidism",
    "message": "Guidelines note that the association between DTG and weight gain may not be causal, instead reflecting comparatively less metabolic toxicity than older ART regimens. This patient gained 9 kg in the past year, but has concurrent untreated hypothyroidism (TSH 12.4, low Free T4) with poor medication adherence, which is a well-established cause of weight gain. The clinician plans to switch from DTG due to weight gain, but this attribution is confounded. Switching DTG may not resolve the weight issue if hypothyroidism remains untreated, and risks losing virological suppression.",
    "issue_type": "plan_review",
    "severity": "moderate",
    "recommended_action": "Correct hypothyroidism and reassess weight before attributing weight gain to DTG. The guideline suggests the DTG-weight association may not be causal.",
    "citations": [
      {"page_number": 7, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p7_c4"}
    ]
  },
  {
    "alert_id": "EX3_003",
    "title": "Dyslipidaemia and hyperglycaemia risk require monitoring",
    "message": "Guidelines identify BMI ≥25, age ≥30, and family history of diabetes as risk factors requiring glucose monitoring in patients on DTG. This patient has BMI 33 and is age 45, meeting multiple risk factors. Fasting glucose is 5.6 mmol/L (borderline). LDL is 4.2, total cholesterol 6.4, and triglycerides 2.3 mmol/L, all elevated. TDF can cause lipid changes, but untreated hypothyroidism is also a major cause of dyslipidaemia and may be contributing. The clinician's plan does not address the abnormal lipids or recommend follow-up glucose monitoring.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Monitor fasting glucose and lipids periodically. Correct hypothyroidism first, then reassess lipids. Consider cardiovascular risk assessment given BMI 33 and dyslipidaemia.",
    "citations": [
      {"page_number": 38, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__p38_c2"}
    ]
  },
  {
    "alert_id": "EX3_004",
    "title": "Viral load monitoring overdue",
    "message": "Guidelines state that patients on DTG-based first-line ART with VL <50 copies/mL for more than one year and reliable adherence can reduce VL monitoring to 12 monthly. The last viral load was <50 copies/mL on 2025-11-10, 106 days before this visit. If the prior VL was also suppressed, the next VL would be due around November 2026. However, if suppression has not yet been documented for over one year, VL should be checked every 6 months, meaning a VL would be due around May 2026. No viral load is ordered in today's plan.",
    "issue_type": "monitoring_gap",
    "severity": "low",
    "recommended_action": "Confirm whether VL suppression has been documented for over one year. If not, schedule VL at 6-month intervals per guideline.",
    "citations": [
      {"page_number": 32, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p32_c1"}
    ]
  }
]
